from collections import deque  # noqa: F401  (reserved for phase 2 implementation)

import pytest


class BoundedQueue:
    """A FIFO queue of integers with a fixed maximum size."""

    def __init__(self, capacity: int) -> None:
        """Create an empty queue holding at most `capacity` items.

        Raises ValueError if capacity is negative.
        """
        if capacity < 0:
            raise ValueError("capacity must be non-negative")
        self._capacity: int = capacity
        self._items: deque[int] = deque()

    def try_put(self, item: int) -> bool:
        """Append item without blocking.

        Returns True if the item was accepted, False if the queue was full.
        """
        if len(self._items) >= self._capacity:
            return False
        self._items.append(item)
        return True


def accepted(cap: int, xs: list[int]) -> int:
    """Put each element of xs into a queue of capacity cap without blocking.

    Stops at the first put that finds the queue full and returns how many
    puts were accepted before that point. Raises ValueError if cap is negative.
    """
    q = BoundedQueue(cap)
    count = 0
    for x in xs:
        if not q.try_put(x):
            break
        count += 1
    return count


def test_try_put_accepts_until_full() -> None:
    q = BoundedQueue(2)
    assert q.try_put(1) is True
    assert q.try_put(2) is True
    assert q.try_put(3) is False


def test_try_put_zero_capacity_rejects() -> None:
    q = BoundedQueue(0)
    assert q.try_put(1) is False


def test_try_put_negative_capacity_raises() -> None:
    with pytest.raises(ValueError):
        BoundedQueue(-1)


def test_accepted_stops_when_full() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_accepted_all_fit() -> None:
    assert accepted(5, [1, 2]) == 2


def test_accepted_empty_input() -> None:
    assert accepted(2, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_accepted_negative_capacity_raises() -> None:
    with pytest.raises(ValueError):
        accepted(-1, [1])
